'use strict'
// An embedded package whose ONLY builtin edge is node:net. cc.ts links
// scr_net_island.c on that edge; the emitted main used to install it on
// node:http/https only, so this package's require('net') failed with "the
// island does not provide the 'node:net' builtin" — from a binary that was
// carrying the bridge. Adding one unused require('http') here made it work
// and changed the binary's size by zero bytes.
const net = require('net')

function isip(addr) {
  return String(net.isIP(addr))
}

function family(addr) {
  if (net.isIPv4(addr)) return 'v4'
  if (net.isIPv6(addr)) return 'v6'
  return 'none'
}

module.exports.isip = isip
module.exports.family = family
